#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

int main(int argc, char *argv[])
{
    const char *NO_INPUT   = "NO_INPUT";
    const char *BAD_INPUT  = "BAD_INPUT";
    const char *BAD_MODE   = "BAD_MODE";
    const char *OUT_OF_RANGE = "OUT_OF_RANGE";

    if (argc < 3) {
        puts(NO_INPUT);
        return 0;
    }

    char *end1, *end2;
    errno = 0;
    long mode = strtol(argv[1], &end1, 10);
    long limit = strtol(argv[2], &end2, 10);

    if (errno != 0 || *end1 != '\0' || *end2 != '\0') {
        puts(BAD_INPUT);
        return 0;
    }

    if (limit < 0) {
        puts(BAD_INPUT);
        return 0;
    }
    if (limit > 100000) {
        puts(OUT_OF_RANGE);
        return 0;
    }

    double sum = 0.0;
    const double C = 1.0; // DAT_00102008 in the original binary

    switch (mode) {
        case 1: { // sum of 1/(i^2)
            for (long i = 1; i <= limit; ++i) {
                sum += C / ((double)i * (double)i);
            }
            break;
        }
        case 2: { // harmonic series sum of 1/i
            for (long i = 1; i <= limit; ++i) {
                sum += C / (double)i;
            }
            break;
        }
        case 3: { // exponential series 1 + 1/1! + 1/2! + ...
            double term = C; // term = 1 / n!
            sum = C; // n = 0 term
            for (long n = 1; n <= limit; ++n) {
                term /= (double)n; // term = 1 / n!
                sum += term;
            }
            break;
        }
        default:
            puts(BAD_MODE);
            return 0;
    }

    printf("%.6f\n", sum);
    return 0;
}
